  readonly List<CheckResult> checks=new List<CheckResult>();readonly List<CaptureResult> captures=new List<CaptureResult>();readonly List<LogEvidence> logs=new List<LogEvidence>();readonly List<UnityEngine.Object> owned=new List<UnityEngine.Object>();
  readonly List<InputPin> files=new List<InputPin>();readonly List<Texture2D> originals=new List<Texture2D>();readonly List<string> originalHashes=new List<string>();readonly List<Material> airMaterials=new List<Material>();
  string output,manifestPath;ComponentInput input;Shader paletteShader;Action<int> done;ProbeReport report;CargoAirSkinRuntimeV21 skins;Camera cameraProbe;SpriteRenderer view;Material baseline;
  public void Begin(string manifest,string directory,Shader exactPinnedShader,Action<int> completed){manifestPath=manifest;output=directory;paletteShader=exactPinnedShader;done=completed;Application.logMessageReceived+=RecordLog;StartCoroutine(Execute());}
  void RecordLog(string message,string stack,LogType type){if(type==LogType.Error||type==LogType.Exception||type==LogType.Assert||type==LogType.Warning)logs.Add(new LogEvidence{type=type.ToString(),message=message,stack=stack});}
  public static string Sha(byte[] bytes){using(var h=SHA256.Create())return BitConverter.ToString(h.ComputeHash(bytes)).Replace("-","").ToLowerInvariant();}
  void Check(string name,bool passed,string detail=""){checks.Add(new CheckResult{name=name,passed=passed,detail=detail});}
  void Require(bool condition,string message){if(!condition)throw new InvalidOperationException(message);}
  void Reject(string name,Action action){bool rejected=false;try{action();}catch(ArgumentException){rejected=true;}catch(InvalidOperationException){rejected=true;}Check(name,rejected);}
  byte[] Read(InputPin p){Require(p!=null&&!String.IsNullOrEmpty(p.path)&&!String.IsNullOrEmpty(p.sha256),"Missing input pin");byte[] b=File.ReadAllBytes(p.path);Require(Sha(b)==p.sha256,"Input pin changed: "+p.path);files.Add(p);return b;}
  static byte[] TopDown(Texture2D t){Color32[] a=t.GetPixels32();byte[] b=new byte[a.Length*4];for(int y=0;y<t.height;y++)for(int x=0;x<t.width;x++){Color32 p=a[(t.height-1-y)*t.width+x];int k=(y*t.width+x)*4;b[k]=p.r;b[k+1]=p.g;b[k+2]=p.b;b[k+3]=p.a;}return b;}
  Texture2D Load(InputPin pin,bool linear,string rgbaHash){var t=new Texture2D(2,2,TextureFormat.RGBA32,false,linear);owned.Add(t);Require(ImageConversion.LoadImage(t,Read(pin),false),"Cannot decode "+pin.path);t.name=Path.GetFileName(pin.path);t.filterMode=FilterMode.Point;t.wrapMode=TextureWrapMode.Clamp;Check(pin.path+" decoded RGBA",Sha(TopDown(t))==rgbaHash,"Texture2D.LoadImage/GetPixels32, includes transparent RGB");return t;}
  T Own<T>(T value)where T:UnityEngine.Object{owned.Add(value);return value;}
  static bool IsSrgb(Texture t){return GraphicsFormatUtility.IsSRGBFormat(t.graphicsFormat);}
  static int Byte(double v){return Math.Max(0,Math.Min(255,(int)Math.Floor(v*255+.5)));}
  static double ToLinear(double s){return s<=.04045?s/12.92:Math.Pow((s+.055)/1.055,2.4);}
  static double ToSrgb(double l){return l<=.0031308?l*12.92:1.055*Math.Pow(l,1/2.4)-.055;}
  static int[] Model(byte[] straight,int p,int mode){int[] r=new int[4];double a=straight[p+3]/255.0;for(int k=0;k<3;k++){double s=straight[p+k]/255.0;r[k]=Byte(mode==0?s*a:mode==1?ToSrgb(ToLinear(s)*a):ToLinear(s)*a);}r[3]=straight[p+3];return r;}
  static int[] Pixel(byte[] data,int p){return new int[]{data[p],data[p+1],data[p+2],data[p+3]};}
  static bool Same(byte[] a,byte[] b){if(a.Length!=b.Length)return false;for(int i=0;i<a.Length;i++)if(a[i]!=b[i])return false;return true;}
  static Comparison Compare(byte[] gpu,byte[] straight,int mode){var r=new Comparison{referenceModel=mode==0?"gamma-premultiply-stored-encoded":mode==1?"linear-premultiply-then-sRGB-encode":"linear-premultiply-stored-linear"};double total=0;for(int p=0;p<gpu.Length;p+=4){int[] expected=Model(straight,p,mode);int ad=Math.Abs(gpu[p+3]-expected[3]);r.comparedPixels++;if(ad>0)r.alphaDifferentPixels++;r.alphaMaxDifference=Math.Max(r.alphaMaxDifference,ad);bool opaque=straight[p+3]==255,partial=straight[p+3]>0&&straight[p+3]<255,diff=false;int maximum=0;if(opaque)r.opaquePixels++;if(partial)r.partialAlphaPixels++;for(int k=0;k<3;k++){int d=Math.Abs(gpu[p+k]-expected[k]);maximum=Math.Max(maximum,d);total+=d;if(d>0)diff=true;}if(diff)r.rgbDifferentPixels++;if(diff&&opaque)r.opaqueRgbDifferentPixels++;r.rgbMaxDifference=Math.Max(r.rgbMaxDifference,maximum);if(opaque)r.opaqueRgbMaxDifference=Math.Max(r.opaqueRgbMaxDifference,maximum);}r.meanRgbAbsoluteDifference=total/(r.comparedPixels*3);r.exactRgbaBytes=r.alphaDifferentPixels==0&&r.rgbDifferentPixels==0;return r;}
  InputPin SavePng(string name,Texture2D texture){string p=Path.Combine(output,name);File.WriteAllBytes(p,ImageConversion.EncodeToPNG(texture));return new InputPin{path=p,sha256=Sha(File.ReadAllBytes(p))};}
  Texture2D FromTopDown(byte[] data,int w,int h){var t=new Texture2D(w,h,TextureFormat.RGBA32,false,true);Color32[] colors=new Color32[w*h];for(int y=0;y<h;y++)for(int x=0;x<w;x++){int k=(y*w+x)*4;colors[(h-1-y)*w+x]=new Color32(data[k],data[k+1],data[k+2],data[k+3]);}t.SetPixels32(colors);t.Apply(false,false);return t;}
  Texture2D Nearest4x(Texture2D inputTexture){var t=new Texture2D(inputTexture.width*4,inputTexture.height*4,TextureFormat.RGBA32,false,true);var source=inputTexture.GetPixels32();var dest=new Color32[t.width*t.height];for(int y=0;y<inputTexture.height;y++)for(int x=0;x<inputTexture.width;x++)for(int dy=0;dy<4;dy++)for(int dx=0;dx<4;dx++)dest[(y*4+dy)*t.width+x*4+dx]=source[y*inputTexture.width+x];t.SetPixels32(dest);t.Apply(false,false);return t;}
  byte[] Canvas(byte[] atlas,int atlasWidth,CaptureInput c){byte[] result=new byte[c.width*c.height*4];int ox=c.rootX-c.anchor[0],oy=c.rootY-c.anchor[1];for(int y=0;y<c.rect[3];y++)for(int x=0;x<c.rect[2];x++){int dx=ox+x,dy=oy+y;if(dx<0||dy<0||dx>=c.width||dy>=c.height)continue;Buffer.BlockCopy(atlas,((c.rect[1]+y)*atlasWidth+c.rect[0]+x)*4,result,(dy*c.width+dx)*4,4);}return result;}
  Texture2D CameraRead(int w,int h,RenderTextureReadWrite mode,Color clear,out bool srgb,out string format,out bool before,out bool after){
   var rt=new RenderTexture(w,h,0,RenderTextureFormat.ARGB32,mode);rt.antiAliasing=1;rt.filterMode=FilterMode.Point;rt.wrapMode=TextureWrapMode.Clamp;rt.useMipMap=false;rt.autoGenerateMips=false;Require(rt.Create(),"Cannot create render target");srgb=rt.sRGB;format=rt.graphicsFormat.ToString();var oldActive=RenderTexture.active;var oldTarget=cameraProbe.targetTexture;bool oldWrite=GL.sRGBWrite;Texture2D readback=null;
   try{cameraProbe.backgroundColor=clear;cameraProbe.targetTexture=rt;before=GL.sRGBWrite;cameraProbe.Render();report.cameraRenderCalls++;report.actualCameraRenderExecuted=true;after=GL.sRGBWrite;RenderTexture.active=rt;readback=new Texture2D(w,h,TextureFormat.RGBA32,false,true);readback.ReadPixels(new Rect(0,0,w,h),0,0,false);readback.Apply(false,false);return readback;}
   finally{cameraProbe.targetTexture=oldTarget;RenderTexture.active=oldActive;GL.sRGBWrite=oldWrite;rt.Release();Destroy(rt);}
  }
