   Check(name+" alpha max delta<=1",result.comparisons[0].alphaMaxDifference<=1,"Raw values/different pixel count retained even on tolerance pass");var samples=new List<ActualPixelSample>();foreach(var s in c.samples){int x=c.rootX-c.anchor[0]+s.x,y=c.rootY-c.anchor[1]+s.y;int pos=(y*c.width+x)*4;bool pinned=true;for(int channel=0;channel<4;channel++)if(expected[pos+channel]!=s.softwareRGBA[channel])pinned=false;Check(name+" sample "+s.role+" matches pinned software bytes",pinned);samples.Add(new ActualPixelSample{role=s.role,x=x,y=y,originalRGBA=s.originalRGBA,softwareRGBA=Pixel(expected,pos),gpuRGBA=Pixel(gpu,pos),gammaPremultiplied=Model(expected,pos,0),linearPremultipliedSrgb=Model(expected,pos,1),linearPremultipliedRaw=Model(expected,pos,2)});}result.samples=samples.ToArray();
   Color bg=new Color(38/255f,51/255f,63/255f,1);if(QualitySettings.activeColorSpace==ColorSpace.Linear)bg=bg.linear;var opaque=CameraRead(c.width,c.height,mode,bg,out srgb,out fmt,out before,out after);result.gpuOpaqueRaw=SavePng(name+"-gpu-opaque-raw.png",opaque);Texture2D display=opaque;if(QualitySettings.activeColorSpace==ColorSpace.Linear&&!srgb){byte[] b=TopDown(opaque);for(int k=0;k<b.Length;k+=4)for(int channel=0;channel<3;channel++)b[k+channel]=(byte)Byte(ToSrgb(b[k+channel]/255.0));display=FromTopDown(b,c.width,c.height);result.gpuOpaqueDisplay=SavePng(name+"-gpu-opaque-linear-to-srgb-display.png",display);}else result.gpuOpaqueDisplay=result.gpuOpaqueRaw;var enlarged=Nearest4x(display);result.gpuOpaqueDisplay4x=SavePng(name+"-gpu-opaque-display-nearest4x.png",enlarged);Destroy(enlarged);if(display!=opaque)Destroy(display);Destroy(opaque);
   skins.Restore(view);Check(name+" restore baseline",view.sharedMaterial==baseline);var baseImage=CameraRead(c.width,c.height,mode,bg,out srgb,out fmt,out before,out after);result.baseOpaqueRaw=SavePng(name+"-base-opaque-raw.png",baseImage);Destroy(baseImage);return result;
  }
  void PrepareAndRender(){
   input=JsonUtility.FromJson<ComponentInput>(File.ReadAllText(manifestPath));Require(input!=null&&input.profiles!=null&&input.profiles.Length==3,"Expected exact3profiles");Read(input.frozenMaterialHandoff);Require(paletteShader&&paletteShader.name==input.shaderName&&paletteShader.isSupported,"Pinned AIR shader is missing/unsupported");Check("actual play mode",Application.isPlaying);Check("exact private shader reference",paletteShader.name=="ElswordPixel/CargoAirControlledPaletteV21");skins=new CargoAirSkinRuntimeV21(paletteShader);baseline=Own(new Material(Shader.Find("Sprites/Default")));var cam=Own(new GameObject("AIR controlled Camera"));cameraProbe=cam.AddComponent<Camera>();cameraProbe.enabled=false;cameraProbe.orthographic=true;cameraProbe.clearFlags=CameraClearFlags.SolidColor;cameraProbe.allowHDR=false;cameraProbe.allowMSAA=false;cameraProbe.allowDynamicResolution=false;cameraProbe.useOcclusionCulling=false;cameraProbe.cullingMask=1<<30;cameraProbe.nearClipPlane=.1f;cameraProbe.farClipPlane=100;var actor=Own(new GameObject("AIR controlled isolated actor"));actor.layer=30;view=actor.AddComponent<SpriteRenderer>();view.sharedMaterial=baseline;
   foreach(var p in input.profiles){
    Require(CargoAirPaletteLookupV21.IsExactAir(p.sourceNPC),"Unexpected source NPC");Read(p.animations);Read(p.clockContract);Texture2D atlas=Load(p.originalAtlas,false,p.originalRgbaSha256),index=Load(p.indexControl,true,p.indexRgbaSha256),palette=Load(p.paletteLUT,false,p.paletteRgbaSha256),expected=Load(p.softwareAtlas,false,p.softwareRgbaSha256);Check(p.sourceNPC+" actual atlas dimensions",atlas.width==p.originalWidth&&atlas.height==p.originalHeight);Check(p.sourceNPC+" actual control dimensions",index.width==atlas.width&&index.height==atlas.height);Check(p.sourceNPC+" actual256LUT",palette.width==256&&palette.height==256);Check(p.sourceNPC+" actual Point",atlas.filterMode==FilterMode.Point&&index.filterMode==FilterMode.Point&&palette.filterMode==FilterMode.Point);Check(p.sourceNPC+" stored data color spaces",!index.isDataSRGB&&atlas.isDataSRGB&&palette.isDataSRGB,"Texture.isDataSRGB describes stored pixel encoding independently of active GPU format. Control non-color; original/palette sRGB encoded.");bool projectLinear=QualitySettings.activeColorSpace==ColorSpace.Linear;Check(p.sourceNPC+" GPU sampling color formats",!IsSrgb(index)&&IsSrgb(atlas)==projectLinear&&IsSrgb(palette)==projectLinear,"Gamma expects UNorm sampling for all3. Linear expects sRGB sampling for original/palette, UNorm for control. No loader, shader or palette changes.");originals.Add(atlas);originalHashes.Add(Sha(TopDown(atlas)));
    byte[] software=CargoAirPaletteLookupV21.Render(TopDown(atlas),TopDown(index),TopDown(palette));Check(p.sourceNPC+" actual software renderer decoded atlas equality",Same(software,TopDown(expected)));index.filterMode=FilterMode.Bilinear;Reject(p.sourceNPC+" reject Bilinear",()=>skins.Register(p.sourceNPC,atlas,index,palette));index.filterMode=FilterMode.Point;skins.Register(p.sourceNPC,atlas,index,palette);
    foreach(var c in p.captures){captures.Add(Capture(p,c,atlas,index,palette,software,RenderTextureReadWrite.sRGB));captures.Add(Capture(p,c,atlas,index,palette,software,RenderTextureReadWrite.Linear));}
    Require(p.captures.Length>=3,"Need neutral/attack/getup per NPC");view.sprite=Own(Sprite.Create(atlas,new Rect(0,0,1,1),Vector2.zero,1));view.sharedMaterial=baseline;skins.Apply(p.sourceNPC,view);Check(p.sourceNPC+" pool skin active",view.sharedMaterial!=baseline);Check(p.sourceNPC+" nonAIR exact guard",!skins.Apply(p.sourceNPC.Replace("_AIR",""),view));Check(p.sourceNPC+" pool restored original material",view.sharedMaterial==baseline);skins.Apply(p.sourceNPC,view);skins.ReleaseRoom();Check(p.sourceNPC+" ReleaseRoom restored",view.sharedMaterial==baseline);skins.Apply(p.sourceNPC,view);skins.ReleaseRoom();Check(p.sourceNPC+" room reentry restored",view.sharedMaterial==baseline);
    Texture2D wrong=Load(p.originalAtlas,false,p.originalRgbaSha256);view.sprite=Own(Sprite.Create(wrong,new Rect(0,0,1,1),Vector2.zero,1));Reject(p.sourceNPC+" wrong same-byte atlas object rejected",()=>skins.Apply(p.sourceNPC,view));Check(p.sourceNPC+" reject leaves baseline",view.sharedMaterial==baseline);var missing=new CargoAirSkinRuntimeV21(paletteShader);Reject(p.sourceNPC+" missing binding rejected",()=>missing.Apply(p.sourceNPC,view));Check(p.sourceNPC+" unrelated skips all bindings",!missing.Apply("NUI_UNRELATED",view));missing.Dispose();
