  IEnumerator Execute(){
   report=new ProbeReport{inputManifestSha256=Sha(File.ReadAllBytes(manifestPath)),unityVersion=Application.unityVersion,graphicsDeviceType=SystemInfo.graphicsDeviceType.ToString(),graphicsDeviceName=SystemInfo.graphicsDeviceName,activeProjectColorSpace=QualitySettings.activeColorSpace.ToString()};
